    # This task colors only closed, rectangular rings. The examples with broken
    # or irregular outlines remain unchanged; complete rectangular rings are
    # filled on the interior except for their center cell.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==1 and q not in seen:
                        seen.add(q); stack.append(q)
            top=min(y for y,x in comp); bot=max(y for y,x in comp)
            left=min(x for y,x in comp); right=max(x for y,x in comp)
            # Outline must be exactly a full rectangle perimeter.
            expected={(top,x) for x in range(left,right+1)} | {(bot,x) for x in range(left,right+1)} | {(y,left) for y in range(top,bot+1)} | {(y,right) for y in range(top,bot+1)}
            if set(comp) != expected:
                continue
            for y in range(top+1,bot):
                for x in range(left+1,right):
                    if (y,x) != ((top+bot)//2,(left+right)//2):
                        out[y][x]=3
    return out
